/**
 * Safe Data Cleanup Script for Auto-generated / Demo Stitch Counts
 * 
 * Usage:
 *   node scripts/clean-stitch-data.js              # Runs dry-run (no DB changes)
 *   node scripts/clean-stitch-data.js --dry-run    # Explicit dry-run
 *   node scripts/clean-stitch-data.js --execute    # Creates CSV backup & cleans DB + fallback json
 *   node scripts/clean-stitch-data.js --undo <csv> # Restores DB + fallback json from CSV backup
 */

const fs = require('fs');
const path = require('path');
const db = require('../config/db');

const BACKUP_DIR = path.join(__dirname, '..', 'backups');
const FALLBACK_JSON_PATH = path.join(__dirname, '..', 'public', 'uploads', 'fallback_designs.json');

// Exact known sample/test stitch tuples: [front, back, sleeve, total]
const SAMPLE_TUPLES = [
  { front: 12000, back: 7500, sleeve: 500, total: 20000 },
  { front: 12000, back: 7500, sleeve: 5300, total: 24800 },
  { front: 12500, back: 8200, sleeve: 4500, total: 25200 },
  { front: 12500, back: 8200, sleeve: null, total: 20700 },
  { front: 2000, back: 7500, sleeve: 700, total: 10200 },
  { front: 5000, back: 6000, sleeve: 1000, total: 12000 },
  { front: 10000, back: 6000, sleeve: null, total: 16000 },
  { front: 11000, back: 6500, sleeve: 4500, total: 22000 },
  { front: 14000, back: 7500, sleeve: 5300, total: 26800 },
  { front: 12000, back: 8000, sleeve: 6000, total: 26000 },
  { front: 12450, back: 18300, sleeve: 6200, total: 36950 },
  { front: 8500, back: 12000, sleeve: 4100, total: 24600 }
];

function isExactSample(front, back, sleeve, total) {
  for (const s of SAMPLE_TUPLES) {
    const fMatch = (s.front === null && (front === null || front === 0)) || Number(s.front) === Number(front);
    const bMatch = (s.back === null && (back === null || back === 0)) || Number(s.back) === Number(back);
    const sMatch = (s.sleeve === null && (sleeve === null || sleeve === 0)) || Number(s.sleeve) === Number(sleeve);
    if (fMatch && bMatch && sMatch) return true;
  }
  return false;
}

function isAllZero(front, back, sleeve, total, stitchCount) {
  const f = Number(front) || 0;
  const b = Number(back) || 0;
  const s = Number(sleeve) || 0;
  const t = Number(total) || 0;
  const sc = Number(stitchCount) || 0;
  return f === 0 && b === 0 && s === 0 && t === 0 && sc === 0;
}

function isLegacyDemoSeedWithoutParts(front, back, sleeve, isManual) {
  const hasNoParts = (!front || Number(front) === 0) &&
                     (!back || Number(back) === 0) &&
                     (!sleeve || Number(sleeve) === 0);
  const notManual = !isManual || Number(isManual) === 0;
  return hasNoParts && notManual;
}

async function getLoggedDesignIds() {
  try {
    const rows = await db.query('SELECT DISTINCT design_id FROM stitch_update_log_items WHERE design_id IS NOT NULL');
    return new Set(rows.map(r => r.design_id));
  } catch (err) {
    return new Set();
  }
}

async function run() {
  const args = process.argv.slice(2);
  const isExecute = args.includes('--execute');
  const undoIndex = args.indexOf('--undo');
  const isUndo = undoIndex !== -1;
  const undoFile = isUndo ? args[undoIndex + 1] : null;

  if (isUndo) {
    await handleUndo(undoFile);
    process.exit(0);
  }

  console.log('========================================================================');
  console.log('🌸 ARUVI EMBROIDERY — STITCH DATA CLEANUP ENGINE');
  console.log(`Mode: ${isExecute ? '🚀 EXECUTE (Applying changes)' : '🔍 DRY-RUN (Preview only)'}`);
  console.log('========================================================================\n');

  await db.initPool();

  if (!db.isConnected()) {
    console.error('❌ Database connection failed. Please ensure MariaDB is running.');
    process.exit(1);
  }

  const loggedIds = await getLoggedDesignIds();
  console.log(`[Audit Log Check]: Found ${loggedIds.size} design(s) with legitimate admin stitch logs (protected).`);

  const rows = await db.query(`
    SELECT id, sku, title, stitch_count, stitch_count_front, stitch_count_back, stitch_count_sleeve, stitch_count_total, stitch_total_manual
    FROM designs
    ORDER BY id ASC
  `);

  const toClean = [];

  for (const d of rows) {
    // If the admin legitimately updated this design via bulk stitch update logs, protect it
    if (loggedIds.has(d.id)) {
      continue;
    }

    const hasAnyStitch = d.stitch_count !== null ||
                         d.stitch_count_front !== null ||
                         d.stitch_count_back !== null ||
                         d.stitch_count_sleeve !== null ||
                         d.stitch_count_total !== null;

    if (!hasAnyStitch) {
      continue;
    }

    let reason = null;

    if (isExactSample(d.stitch_count_front, d.stitch_count_back, d.stitch_count_sleeve, d.stitch_count_total)) {
      reason = 'Exact autogenerated sample tuple match';
    } else if (isAllZero(d.stitch_count_front, d.stitch_count_back, d.stitch_count_sleeve, d.stitch_count_total, d.stitch_count)) {
      reason = 'All stitch fields equal to 0';
    } else if (isLegacyDemoSeedWithoutParts(d.stitch_count_front, d.stitch_count_back, d.stitch_count_sleeve, d.stitch_total_manual)) {
      reason = 'Legacy demo seed total with 0/NULL parts';
    }

    if (reason) {
      toClean.push({
        id: d.id,
        sku: d.sku || `ID-${d.id}`,
        title: d.title || 'Untitled',
        old_front: d.stitch_count_front,
        old_back: d.stitch_count_back,
        old_sleeve: d.stitch_count_sleeve,
        old_total: d.stitch_count_total,
        old_stitch_count: d.stitch_count,
        old_manual: d.stitch_total_manual,
        reason
      });
    }
  }

  console.log(`\n📊 Dry-Run Report:`);
  console.log(`Total designs inspected: ${rows.length}`);
  console.log(`Designs marked for cleanup: ${toClean.length}`);
  console.log(`Legitimate admin designs kept untouched: ${rows.length - toClean.length}`);

  console.log('\n--- TARGETED SKUs & VALUES ---');
  console.table(toClean.map(item => ({
    ID: item.id,
    SKU: item.sku,
    Front: item.old_front,
    Back: item.old_back,
    Sleeve: item.old_sleeve,
    Total: item.old_total,
    StitchCount: item.old_stitch_count,
    Reason: item.reason
  })));

  if (!isExecute) {
    console.log('\n⚠️  DRY-RUN COMPLETE: No changes were made to database or disk.');
    console.log('To execute cleanup and create backup, run:');
    console.log('  node scripts/clean-stitch-data.js --execute\n');
    process.exit(0);
  }

  // EXECUTE MODE:
  // 1. Create CSV Backup
  if (!fs.existsSync(BACKUP_DIR)) {
    fs.mkdirSync(BACKUP_DIR, { recursive: true });
  }

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const backupFilename = `stitch_backup_${timestamp}.csv`;
  const backupFilePath = path.join(BACKUP_DIR, backupFilename);

  const csvHeader = 'id,sku,title,stitch_count,stitch_count_front,stitch_count_back,stitch_count_sleeve,stitch_count_total,stitch_total_manual,reason\n';
  const csvLines = toClean.map(item => {
    const safeTitle = `"${(item.title || '').replace(/"/g, '""')}"`;
    return [
      item.id,
      item.sku,
      safeTitle,
      item.old_stitch_count ?? '',
      item.old_front ?? '',
      item.old_back ?? '',
      item.old_sleeve ?? '',
      item.old_total ?? '',
      item.old_manual ?? 0,
      `"${item.reason}"`
    ].join(',');
  }).join('\n');

  fs.writeFileSync(backupFilePath, csvHeader + csvLines, 'utf8');
  console.log(`\n💾 Backup CSV generated successfully:`);
  console.log(`   ${backupFilePath}`);

  // 2. Perform DB Update in MariaDB
  const targetIds = toClean.map(t => t.id);
  if (targetIds.length > 0) {
    const placeholders = targetIds.map(() => '?').join(',');
    await db.query(`
      UPDATE designs 
      SET 
        stitch_count = NULL,
        stitch_count_front = NULL,
        stitch_count_back = NULL,
        stitch_count_sleeve = NULL,
        stitch_count_total = NULL,
        stitch_total_manual = 0
      WHERE id IN (${placeholders})
    `, targetIds);
    console.log(`✅ Successfully updated ${targetIds.length} rows in database to NULL.`);
  }

  // 3. Clean fallback_designs.json
  if (fs.existsSync(FALLBACK_JSON_PATH)) {
    try {
      const fallbackContent = fs.readFileSync(FALLBACK_JSON_PATH, 'utf8');
      const fallbackDesigns = JSON.parse(fallbackContent);
      let fallbackModifiedCount = 0;

      for (const d of fallbackDesigns) {
        if (isExactSample(d.stitch_count_front, d.stitch_count_back, d.stitch_count_sleeve, d.stitch_count_total) ||
            isAllZero(d.stitch_count_front, d.stitch_count_back, d.stitch_count_sleeve, d.stitch_count_total, d.stitch_count) ||
            isLegacyDemoSeedWithoutParts(d.stitch_count_front, d.stitch_count_back, d.stitch_count_sleeve, d.stitch_total_manual)) {
          d.stitch_count = null;
          d.stitch_count_front = null;
          d.stitch_count_back = null;
          d.stitch_count_sleeve = null;
          d.stitch_count_total = null;
          d.frontStitchCount = null;
          d.backStitchCount = null;
          d.sleeveStitchCount = null;
          d.totalStitchCount = null;
          d.stitch_total_manual = 0;
          d.stitchTotalManual = 0;
          fallbackModifiedCount++;
        }
      }

      fs.writeFileSync(FALLBACK_JSON_PATH, JSON.stringify(fallbackDesigns, null, 2), 'utf8');
      console.log(`✅ Cleaned ${fallbackModifiedCount} item(s) in fallback_designs.json.`);
    } catch (fbErr) {
      console.warn('⚠️ Warning cleaning fallback_designs.json:', fbErr.message);
    }
  }

  console.log('\n========================================================================');
  console.log('🎉 CLEANUP COMPLETED SUCCESSFULLY!');
  console.log(`Undo command available if needed:`);
  console.log(`  node scripts/clean-stitch-data.js --undo "${backupFilePath}"`);
  console.log('========================================================================\n');
  process.exit(0);
}

async function handleUndo(csvFilePath) {
  if (!csvFilePath || !fs.existsSync(csvFilePath)) {
    console.error(`❌ Undo file not found: ${csvFilePath}`);
    process.exit(1);
  }

  console.log(`\n🔄 Restoring stitch counts from backup: ${csvFilePath}...`);
  const content = fs.readFileSync(csvFilePath, 'utf8');
  const lines = content.split('\n').filter(l => l.trim().length > 0);
  const dataLines = lines.slice(1); // skip header

  let restoredCount = 0;

  for (const line of dataLines) {
    const parts = line.split(',');
    const id = parseInt(parts[0], 10);
    const stitch_count = parts[3] !== '' ? parseInt(parts[3], 10) : null;
    const stitch_count_front = parts[4] !== '' ? parseInt(parts[4], 10) : null;
    const stitch_count_back = parts[5] !== '' ? parseInt(parts[5], 10) : null;
    const stitch_count_sleeve = parts[6] !== '' ? parseInt(parts[6], 10) : null;
    const stitch_count_total = parts[7] !== '' ? parseInt(parts[7], 10) : null;
    const stitch_total_manual = parts[8] !== '' ? parseInt(parts[8], 10) : 0;

    await db.query(`
      UPDATE designs 
      SET 
        stitch_count = ?,
        stitch_count_front = ?,
        stitch_count_back = ?,
        stitch_count_sleeve = ?,
        stitch_count_total = ?,
        stitch_total_manual = ?
      WHERE id = ?
    `, [stitch_count, stitch_count_front, stitch_count_back, stitch_count_sleeve, stitch_count_total, stitch_total_manual, id]);

    restoredCount++;
  }

  console.log(`✅ Restored ${restoredCount} design(s) to original values.`);
}

run().catch(err => {
  console.error('❌ Cleanup failed:', err);
  process.exit(1);
});
